def capability_catalog() -> list[dict[str, Any]]:
    """Return read-only declarative metadata for all registered semantic capabilities."""
    items: list[dict[str, Any]] = []
    for code in registered_capabilities():
        cap = _CAPABILITIES[code]
        meta = _CAPABILITY_METADATA.get(code, {})
        items.append(
            {
                "code": cap.code,
                "modes": list(cap.modes),
                "bounded_context_rule": meta.get(
                    "bounded_context_rule",
                    "CAPABILITY_OWNED",
                ),
                "allowed_constraints": list(
                    meta.get("allowed_constraints", ())
                ),
                "allowed_path_roots": list(
                    meta.get("allowed_path_roots", ())
                ),
                "raw_worker_fields_forbidden": True,
            }
        )
    return items

@router.get("/capabilities")
def list_worker_semantic_capabilities(
    current_user: dict = Depends(WORKER_ADMIN_DEPENDENCY),
    authorization: str | None = Header(default=None, alias="Authorization"),
):
    """Read-only discovery of registered semantic capabilities and allowed constraints."""
    _require_ingress_mcp_scope(
        authorization=authorization,
        required_scope="worker:status",
        current_user=current_user,
    )
    del current_user
    from .semantic_capabilities import (
        RAW_WORKER_FIELDS_FORBIDDEN,
        capability_catalog,
    )

    return {
        "schema": "edarsahub.worker-semantic-capabilities.v1",
        "production_allowed": False,
        "raw_worker_fields_forbidden": list(RAW_WORKER_FIELDS_FORBIDDEN),
        "capabilities": capability_catalog(),
    }

def submit_objective_tool(
    objective: str,
    bounded_context: str,
    mode: str,
    capability: str,
    request_key: str | None = None,
    constraints: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Submit one approved semantic objective to the EDARSAHUB Universal Worker.

    Raw edarsahub.worker-job.v2 fields (actions, checks, production_allowed,
    requester, target_repo, target_branch) are backend-owned and MUST NEVER be
    passed inside constraints (doing so returns
    VALIDATION_ERROR_422:SEMANTIC_CONSTRAINTS_UNSUPPORTED).

    Registered capabilities and exact allowed constraint keys:
    - READ_ONLY_CANARY (mode=READ_ONLY): constraints={}
    - REPOSITORY_CONTRACT_AUDIT_BOUNDED (mode=READ_ONLY, any valid bounded_context):
      constraints={"paths": [...], "search_terms": [...], "max_results": 1..100};
      paths must start with backend/modules/, backend/tests/, frontend/src/, or tools/mirror_sync/.
    - REPOSITORY_CONTRACT_AUDIT (mode=READ_ONLY, bounded_context="RH" only): constraints={}
    - WORKER_RESULT_SEMANTIC_EXTRACT (mode=READ_ONLY): constraints={"source_job_id": "..."}
    - WORKER_RESULT_DETAIL_READ (mode=READ_ONLY): constraints={"source_job_id": "..."}
    - WORKER_MAINTENANCE_HISTORY_READONLY (mode=READ_ONLY, bounded_context="WORKER_REPAIR_KNOWLEDGE_LOOP"): constraints={}
    - WORKER_PYTEST_CERTIFICATION_READONLY (mode=READ_ONLY, bounded_context="WORKER_REPAIR_KNOWLEDGE_LOOP"): constraints={}
    - WORKER_REPAIR_BOUNDED (mode=MUTATION, bounded_context="WORKER_RUNTIME_CONVERGENCE"):
      constraints={"incident_id": "...", "capability_code": "..."}
    """
    if constraints is not None and not isinstance(constraints, dict):
        raise ToolError("VALIDATION_ERROR_422:SEMANTIC_CONSTRAINTS_INVALID")
    payload: dict[str, Any] = {
        "objective": objective,
        "bounded_context": bounded_context,
        "mode": mode,
        "capability": capability,
        "constraints": constraints or {},
    }

def test_g3_r2_capability_catalog_exposes_all_registered_capabilities_and_constraints():
    from modules.worker_ingress.semantic_capabilities import (
        RAW_WORKER_FIELDS_FORBIDDEN,
        capability_catalog,
    )

    catalog = capability_catalog()
    by_code = {item["code"]: item for item in catalog}
    assert tuple(sorted(by_code)) == registered_capabilities()
    assert "actions" in RAW_WORKER_FIELDS_FORBIDDEN
    assert "checks" in RAW_WORKER_FIELDS_FORBIDDEN
    assert "production_allowed" in RAW_WORKER_FIELDS_FORBIDDEN

    bounded = by_code["REPOSITORY_CONTRACT_AUDIT_BOUNDED"]
    assert bounded["modes"] == ["READ_ONLY"]
    assert bounded["allowed_constraints"] == ["max_results", "paths", "search_terms"]
    assert bounded["raw_worker_fields_forbidden"] is True
    assert "tools/mirror_sync/" in bounded["allowed_path_roots"]

    canary = by_code["READ_ONLY_CANARY"]
    assert canary["allowed_constraints"] == []

    rh_audit = by_code["REPOSITORY_CONTRACT_AUDIT"]
    assert rh_audit["bounded_context_rule"] == "RH"
    assert rh_audit["allowed_constraints"] == []


def test_g3_r2_capabilities_discovery_route_is_registered_and_status_scoped():
    import ast

    routes = set()
    for node in ast.walk(ast.parse(ROUTES)):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        for decorator in node.decorator_list:
            if not isinstance(decorator, ast.Call):
                continue
            if not isinstance(decorator.func, ast.Attribute):
                continue
            if not isinstance(decorator.func.value, ast.Name) or decorator.func.value.id != "router":
                continue
            if decorator.func.attr == "get" and decorator.args:
                route = decorator.args[0]
                if isinstance(route, ast.Constant) and isinstance(route.value, str):
                    routes.add(route.value)

    assert "/capabilities" in routes
    assert 'required_scope="worker:status"' in ROUTES
